{
  "entities": [
    {
      "type": "EXCLUSION",
      "name": "Choroba",
      "description": "Wyłączenie obejmuje obrażenia fizyczne powstałe w wyniku choroby, niepełnosprawności fizycznej, zaburzeń psychicznych lub zaburzeń zachowania sklasyfikowanych jako F00-F99 w rozumieniu Międzynarodowej Klasyfikacji Chorób i Problemów Zdrowotnych ICD-10 oraz medycznych lub chirurgicznych skutków ich leczenia, lumbago, rwy kulszowej, zwyrodnienia kręgosłupa, dyskopatii, kręgozmyku, przepukliny krążka miażdżystego, przepukliny, zatrucia ptomainami lub infekcji bakteryjnej (z wyjątkiem infekcji ropnej powstałej w wyniku przypadkowego skaleczenia lub zranienia).",
      "dowód": "choroby, niepełnosprawności fizycznej, zaburzeń psychicznych lub zaburzeń zachowania sklasyfikowanych jako F00-F99 w rozumieniu Międzynarodowej Klasyfikacji Chorób i Problemów Zdrowotnych ICD-10 oraz medycznych lub chirurgicznych skutków ich leczenia, lumbago, rwy kulszowej, zwyrodnienia kręgosłupa, dyskopatii, kręgozmyku, przepukliny krążka miażdżystego, przepukliny, zatrucia ptomainami lub infekcji bakteryjnej (z wyjątkiem infekcji ropnej powstałej w wyniku przypadkowego skaleczenia lub zranienia)"
    },
    {
      "type": "EXCLUSION",
      "name": "Stan po spożyciu alkoholu",
      "description": "Wyłączenie obejmuje obrażenia fizyczne powstałe w wyniku wypadku wynikłego z faktu pozostawania odpowiednio przez Ubezpieczonego, Małżonka lub Partnera, lub Dziecko w stanie po spożyciu alkoholu, leków, z wyjątkiem zażywanych zgodnie z zaleceniem lekarza, narkotyków lub innych substancji toksycznych.",
      "dowód": "wypadku wynikłego z faktu pozostawania odpowiednio przez Ubezpieczonego, Małżonka lub Partnera, lub Dziecko w stanie po spożyciu alkoholu, leków, z wyjątkiem zażywanych zgodnie z zaleceniem lekarza, narkotyków lub innych substancji toksycznych"
    },
    {
      "type": "EXCLUSION",
      "name": "Masowe skażenie",
      "description": "Wyłączenie obejmuje zdarzenia związane z masowym skażeniem chemicznym, biologicznym lub radioaktywnym spowodowanym działaniem broni lub urządzenia wykorzystującego energię rozszczepienia jądrowego lub promieniotwórczość.",
      "dowód": "zdarzenia związanego z masowym skażeniem chemicznym, biologicznym lub radioaktywnym spowodowanym działaniem broni lub urządzenia wykorzystującego energię rozszczepienia jądrowego lub promieniotwórczość"
    },
    {
      "type": "EXCLUSION",
      "name": "Działania wojenne",
      "description": "Wyłączenie obejmuje działania wojenne, czynny udział w aktach terroru lub masowych rozruchach społecznych.",
      "dowód": "działań wojennych, czynnego udziału w aktach terroru lub masowych rozruchach społecznych"
    },
    {
      "type": "EXCLUSION",
      "name": "Wykonywanie czynności służbowych",
      "description": "Wyłączenie obejmuje wykonywanie czynności służbowych/zawodowych właściwych dla policji, wojska, Straży Granicznej, straży pożarnej, straży gminnej (miejskiej), bądź jednostki pomocniczej lub cywilnej działającej w strukturach armii, niezależnie od formy zatrudnienia lub pełnienia służby.",
      "dowód": "wykonywania czynności służbowych/zawodowych właściwych dla policji, wojska, Straży Granicznej, straży pożarnej, straży gminnej (miejskiej), bądź jednostki pomocniczej lub cywilnej działającej w strukturach armii, niezależnie od formy zatrudnienia lub pełnienia służby"
    },
    {
      "type": "EXCLUSION",
      "name": "Uprawianie sportów ekstremalnych",
      "description": "Wyłączenie obejmuje uprawianie wspinaczki, skoków spadochronowych, lotów szybowcowych, paralotniarstwa, nurkowania, speleologii, sportów walki, sportów motorowych lub motorowodnych, uczestnictwa w rajdach samochodowych lub rajdach motocyklowych, jazdy motocyklem poza drogami w rozumieniu przepisów o ruchu drogowym, konnych.",
      "dowód": "uprawiania wspinaczki, skoków spadochronowych, lotów szybowcowych, paralotniarstwa, nurkowania, speleologii, sportów walki, sportów motorowych lub motorowodnych, uczestnictwa w rajdach samochodowych lub rajdach motocyklowych, jazdy motocyklem poza drogami w rozumieniu przepisów o ruchu drogowym, konnych"
    },
    {
      "type": "EXCLUSION",
      "name": "Podróż statkiem powietrznym",
      "description": "Wyłączenie obejmuje podróż jakimkolwiek statkiem powietrznym w charakterze pasażera lub innym, z wyjątkiem lotu w charakterze pasażera samolotem pasażerskich licencjonowanych linii lotniczych.",
      "dowód": "podróży jakimkolwiek statkiem powietrznym w charakterze pasażera lub innym, z wyjątkiem lotu w charakterze pasażera samolotem pasażerskich licencjonowanych linii lotniczych"
    }
  ]
}
